def inside_out(x: str) -> str:
    def transform(word: str) -> str:
        n = len(word)
        if n <= 1:
            return word
        left = []
        right = []
        mid = []
        for i in range(n):
            if i < n // 2:
                left.append(word[i])
            elif i > n - 1 - n // 2:
                right.append(word[i])
            else:
                mid.append(word[i])
        result = []
        l_ptr = 0
        r_ptr = 0
        for i in range(n):
            if i < len(left):
                result.append(left[l_ptr])
                l_ptr += 1
            elif i >= n - len(right):
                result.append(right[r_ptr])
                r_ptr += 1
            else:
                result.extend(mid)
        return "".join(result)

    words = x.split()
    transformed_words = [transform(w) for w in words]
    return " ".join(transformed_words)
